journals.script:
{
is_shown_when_inactive = {
	has_variable = ywc_v03_initialized
	NOT = { has_variable = ywc_c06_started }
	OR = {
		AND = { ywc_c06_is_pool_tag = yes OR = { ywc_c06_case_ready_local = yes var:ywc_c06_case_open ?= 1 } }
		AND = { c:SHU ?= this var:ywc_c06_case_open ?= 1 }
		AND = { c:BUR ?= this var:ywc_c06_case_open ?= 1 }
	}
}
possible = {
	has_variable = ywc_v03_initialized
	ywc_v03_has_capacity = yes
	NOT = { has_variable = ywc_c06_started }
	OR = {
		AND = { ywc_c06_is_pool_tag = yes ywc_c06_case_ready_local = yes }
		AND = { ywc_c06_is_pool_tag = yes var:ywc_c06_case_open ?= 1 }
		AND = { c:SHU ?= this var:ywc_c06_case_open ?= 1 }
		AND = { c:BUR ?= this var:ywc_c06_case_open ?= 1 }
	}
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c06_started } }
		set_variable = { name = ywc_c06_started value = 1 }
		set_variable = { name = ywc_c06_popup_epoch value = 0 }
		set_variable = { name = ywc_c06_wait_age value = 0 }
		change_variable = { name = ywc_v03_active_arc_count add = 1 }
		change_variable = { name = ywc_v03_visible_task_count add = 1 }
	}
	if = { limit = { NOT = { has_variable = ywc_c06_popup_epoch } } set_variable = { name = ywc_c06_popup_epoch value = 0 } }
	if = { limit = { ywc_c06_is_pool_tag = yes NOT = { has_variable = ywc_c06_role } NOT = { has_variable = ywc_c06_case_open } } set_variable = { name = ywc_c06_role value = 1 } }
	if = { limit = { c:SHU ?= this NOT = { has_variable = ywc_c06_role } } set_variable = { name = ywc_c06_role value = 2 } }
	if = { limit = { c:BUR ?= this NOT = { has_variable = ywc_c06_role } } set_variable = { name = ywc_c06_role value = 3 } }
	if = { limit = { var:ywc_c06_role ?= 1 NOT = { has_variable = ywc_c06_stage } }
		set_variable = { name = ywc_c06_case_open value = 1 }
		set_variable = { name = ywc_c06_stage value = 1500 }
		set_variable = { name = ywc_c06_pending value = 1500 }
	}
	if = { limit = { OR = { var:ywc_c06_role ?= 2 var:ywc_c06_role ?= 3 var:ywc_c06_role ?= 5 } NOT = { has_variable = ywc_c06_stage } } set_variable = { name = ywc_c06_stage value = 1518 } }
	if = { limit = { var:ywc_c06_role ?= 1 } ywc_c06_select_claimants = yes }
}
on_monthly_pulse = {
	effect = {
		if = { limit = { var:ywc_c06_role ?= 1 var:ywc_c06_stage ?= 1513 }
			change_variable = { name = ywc_c06_wait_age add = 1 }
			if = { limit = { OR = { ywc_c06_replies_resolved = yes var:ywc_c06_wait_age >= 12 } } ywc_c06_after_replies = yes }
		}
		if = { limit = { OR = { var:ywc_c06_role ?= 2 var:ywc_c06_role ?= 3 } var:ywc_c06_stage ?= 1518 }
			change_variable = { name = ywc_c06_wait_age add = 1 }
			if = { limit = { OR = { ywc_c06_proposer_gone = yes var:ywc_c06_wait_age >= 36 } } ywc_c06_close_no_talks = yes }
		}
		if = { limit = { OR = { var:ywc_c06_role ?= 2 var:ywc_c06_role ?= 3 } OR = { var:ywc_c06_stage ?= 1502 var:ywc_c06_stage ?= 1503 } NOT = { ywc_c06_proposer_awaiting = yes } }
			ywc_c06_close_no_talks = yes
		}
		if = { limit = { ywc_c06_pool_delivery_1500 = yes } trigger_event = { id = ywc_crisis.1500 } }
		if = { limit = { ywc_c06_pool_delivery_1501 = yes } trigger_event = { id = ywc_crisis.1501 } }
		if = { limit = { ywc_c06_shu_delivery_1502 = yes } trigger_event = { id = ywc_crisis.1502 } }
		if = { limit = { ywc_c06_bur_delivery_1502 = yes } trigger_event = { id = ywc_crisis.1502 } }
		if = { limit = { ywc_c06_bur_delivery_1503 = yes } trigger_event = { id = ywc_crisis.1503 } }
		if = { limit = { ywc_c06_pool_delivery_1503 = yes } trigger_event = { id = ywc_crisis.1503 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c06_shares_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c06_started
	var:ywc_c06_shares_open ?= 1
	ywc_c06_is_participant = yes
	NOT = { has_variable = ywc_c06_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c06_popup_epoch } } set_variable = { name = ywc_c06_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
		if = { limit = { ywc_c06_pool_delivery_1504 = yes } trigger_event = { id = ywc_crisis.1504 } }
		if = { limit = { ywc_c06_pool_delivery_1505 = yes } trigger_event = { id = ywc_crisis.1505 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c06_review_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c06_started
	var:ywc_c06_review_open ?= 1
	ywc_c06_is_participant = yes
	NOT = { has_variable = ywc_c06_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c06_popup_epoch } } set_variable = { name = ywc_c06_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
		if = { limit = { OR = { var:ywc_c06_role ?= 2 var:ywc_c06_role ?= 3 } var:ywc_c06_stage ?= 1506 }
			change_variable = { name = ywc_c06_wait_age add = 1 }
			if = { limit = { OR = { ywc_c06_proposer_gone = yes var:ywc_c06_wait_age >= 12 } } ywc_c06_transit_unilateral = yes }
		}
		if = { limit = { var:ywc_c06_role ?= 1 var:ywc_c06_stage ?= 1512 }
			change_variable = { name = ywc_c06_wait_age add = 1 }
			if = { limit = { OR = { ywc_c06_claimant_a_gone = yes var:ywc_c06_wait_age >= 24 } } ywc_c06_transit_skip = yes }
		}
		if = { limit = { NOT = { has_variable = ywc_c06_signatory } var:ywc_c06_stage ?= 1514 }
			change_variable = { name = ywc_c06_wait_age add = 1 }
			if = { limit = { OR = { ywc_c06_proposer_gone = yes var:ywc_c06_wait_age >= 24 } } ywc_c06_renegotiation_self = yes }
		}
		if = { limit = { OR = { has_variable = ywc_c06_signatory has_variable = ywc_c06_signatory_limited } var:ywc_c06_stage ?= 1515 }
			change_variable = { name = ywc_c06_wait_age add = 1 }
			if = { limit = { OR = { ywc_c06_proposer_gone = yes var:ywc_c06_wait_age >= 36 } } ywc_c06_self_settle = yes }
		}
		if = { limit = { var:ywc_c06_stage ?= 1511 }
			change_variable = { name = ywc_c06_wait_age add = 1 }
			if = { limit = { var:ywc_c06_wait_age >= 12 }
				set_variable = { name = ywc_c06_aftermath value = 1 }
				set_variable = { name = ywc_c06_stage value = 1516 }
				set_variable = { name = ywc_c06_wait_age value = 0 }
				if = { limit = { has_variable = ywc_c06_pending } remove_variable = ywc_c06_pending }
				ywc_c06_release_capacity = yes
			}
		}
		if = { limit = { ywc_c06_shu_delivery_1506 = yes } trigger_event = { id = ywc_crisis.1506 } }
		if = { limit = { ywc_c06_bur_delivery_1506 = yes } trigger_event = { id = ywc_crisis.1506 } }
		if = { limit = { ywc_c06_pool_delivery_1512 = yes } trigger_event = { id = ywc_crisis.1506 } }
		if = { limit = { ywc_c06_pool_delivery_1507 = yes } trigger_event = { id = ywc_crisis.1507 } }
		if = { limit = { ywc_c06_pool_delivery_1508 = yes } trigger_event = { id = ywc_crisis.1508 } }
		if = { limit = { ywc_c06_pool_delivery_1509 = yes } trigger_event = { id = ywc_crisis.1509 } }
		if = { limit = { ywc_c06_shu_delivery_1509 = yes } trigger_event = { id = ywc_crisis.1509 } }
		if = { limit = { ywc_c06_bur_delivery_1509 = yes } trigger_event = { id = ywc_crisis.1509 } }
		if = { limit = { ywc_c06_pool_delivery_1510 = yes } trigger_event = { id = ywc_crisis.1510 } }
		if = { limit = { ywc_c06_shu_delivery_1510 = yes } trigger_event = { id = ywc_crisis.1510 } }
		if = { limit = { ywc_c06_bur_delivery_1510 = yes } trigger_event = { id = ywc_crisis.1510 } }
		if = { limit = { ywc_c06_pool_delivery_1511 = yes } trigger_event = { id = ywc_crisis.1511 } }
		if = { limit = { ywc_c06_shu_delivery_1511 = yes } trigger_event = { id = ywc_crisis.1511 } }
		if = { limit = { ywc_c06_bur_delivery_1511 = yes } trigger_event = { id = ywc_crisis.1511 } }
	}
}
}
